@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/registers/geoprocessing/NdviComputation> ;
            sh:resultMessage "An activity type must be a sub-class (directly or indirectly) of prov:Activity." ;
            sh:resultPath [ sh:oneOrMorePath rdfs:subClassOf ] ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:HasValueConstraintComponent ;
            sh:sourceShape [ sh:hasValue prov:Activity ;
                    sh:message "An activity type must be a sub-class (directly or indirectly) of prov:Activity." ;
                    sh:path [ sh:oneOrMorePath rdfs:subClassOf ] ] ] .

